def run(context):
    # Process company_data to synthesize a growth summary
    growth_summary = {
        'strong_growth_companies': []
    }
    # Example processing
    for record in context['company_data']:
        if record['growth_yoy_revenue_pct'] > 20:
            growth_summary['strong_growth_companies'].append(
                record['symbol']
            )
    return growth_summary

def run(context):
    insider_alerts = context['insider_context']
    tech_confirms = context['technical_confirmation']
    combined = []
    for symbol in insider_alerts:
        if symbol in tech_confirms:
            combined.append((symbol, tech_confirms[symbol]['technical_score']))
    ranked = sorted(combined, key=lambda x: x[1], reverse=True)
    return ranked

def run(context):
    # Sample implementation of a read-only outcome analysis
    signals = context['signals.signal_log']
    outcomes = {'outcome_summary': {}, 'winner_patterns': [], 'failure_patterns': []}
    for signal in signals:
        if signal['hit_target']:
            outcomes['winner_patterns'].append(signal)
        elif signal['hit_stop']:
            outcomes['failure_patterns'].append(signal)
    outcomes['outcome_summary'] = {
        'total_signals': len(signals),
        'success_rate': len(outcomes['winner_patterns']) / len(signals) if len(signals) > 0 else 0,
        'failure_rate': len(outcomes['failure_patterns']) / len(signals) if len(signals) > 0 else 0
    }
    return outcomes

